// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(uint256 amount, address target) public {
        vm.assume(amount > 0);
        vm.assume(target > address(9) || target < address(1));
        vm.assume(target != address(c));
        address owner = c.Owner();
        vm.deal(owner, amount);
        vm.prank(owner);
        uint256 ownerBalanceBefore = owner.balance;
        uint256 balanceBefore = address(c).balance;
        bool ok;
        try c.Command{value: amount}(target, "") {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && owner.balance == ownerBalanceBefore - amount && address(c).balance == balanceBefore);
    }
}
